(* [comment removed for export] *)
Lemma xpres_drop_frame : forall LB SP SP' X X' m m',
  xpres LB SP X m m' -> SP <= SP' ->
  (forall b, In b LB -> blk_addr b + blk_size b <= hceil) ->
  (forall a, rin_ivs X a -> hceil <= a < SP' /\ ~ rin_ivs X' a \/ rin_ivs X' a) ->
  xpres LB SP' X' m m'.
Proof.
  intros LB SP SP' X X' m m' XP LE HB HX a Ha [HC NX]. apply XP; [exact Ha|]. split.
  - destruct HC as [HC|[HC|HC]]; [left; lia| right; left; exact HC| right; right; exact HC].
  - intros R. destruct (HX a R) as [[K1 K2]|K]; [| exact (NX K)].
    destruct HC as [HC|[[HC _]|(b & Hb & Hr)]]; [lia| hcb; lia|]. pose proof (HB b Hb). lia.
Qed.

(* [comment removed for export] *)
Lemma ImplBlock_intro_fresh : forall LB m p q j7,
  In (p, q, 96) LB -> rblock_range q 96 ->
  rw_cells rsegs m q (SpcHdrCells (mkSPC VP_SPCI_IMPL 1 1 1) j7) ->
  rw_cells rsegs m (q + 32) [CB 64 (zeros 64)] ->
