  Definition shc_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (E PC q lo : Z) (junkB : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j7,
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 q) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch [(lo, bv_unsigned sp); (PC, PC + 8); (q, q + 32)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' PC [C8 (Z_to_bv 64 q)]
      /\ rw_cells rsegs m' q (SpcHdrCells (mkSPC (shc_vp E) 1 1 0) j7)
      /\ rw_cells rsegs m' (q + 32) [CB (Z.to_nat (shc_size E - 32)) (skipn 32 junkB)].

  Lemma shc_seg2 : forall (E : Z), shc_entry_ok E ->
    forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (PC q lo : Z) (junkF junkB : list byte),
    rw_cells rsegs m (bv_unsigned sp + -32) [CB 8 junkF; C8 s1; C8 s0; C8 ra] ->
    rw_cells rsegs m PC [C8 (Z_to_bv 64 0)] ->
    rw_cells rsegs m q [CB (Z.to_nat (shc_size E)) junkB] ->
    stk rsegs m lo (bv_unsigned sp + -32) -> lo + 32 <= bv_unsigned sp -> (PC + 8 <= lo \/ bv_unsigned sp <= PC) ->
    0 < q -> q + shc_size E <= lo -> (PC + 8 <= q \/ q + shc_size E <= PC) ->
    mem_inv rsegs m ->
    evt rsegs (shc_seg2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc E PC q lo junkB m)
      (MS (mkR (Z_to_bv 64 (E + 36)) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2
               (Z_to_bv 64 PC) (Z_to_bv 64 0) (Z_to_bv 64 q) a1 a2 a3 a4 a5 a6 a7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 (E + 36)) fc None m (seg_rom rsegs)).
