  (* [comment removed for export] *)
  Definition shcount_ctor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (E : Z) (s : PState) (LB : list block) (PC lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p : bptr) (q : Z) j7 junk,
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 q) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range q (shc_size E) /\ hs_RHEAP H s' ((p, q, shc_size E) :: LB) m'
      /\ rw_cells rsegs m' PC [C8 (Z_to_bv 64 q)]
      /\ rw_cells rsegs m' q (SpcHdrCells (mkSPC (shc_vp E) 1 1 0) j7)
      /\ rw_cells rsegs m' (q + 32) [CB (Z.to_nat (shc_size E - 32)) junk]
      /\ xpres LB (bv_unsigned sp) [(PC, PC + 8)] m m'.

  Definition shcount_ctor_stmt (E : Z) : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (PC lo B : Z) (errv : word) (jpc : list byte),
      a0 = Z_to_bv 64 PC -> a1 = Z_to_bv 64 0 ->
      rw_cells rsegs m PC [CB 8 jpc] -> bv_unsigned sp <= PC -> PC + 8 <= B ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + shc_size E <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - SHCOUNT_CTOR_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      hs_SR H (shcount_ctor_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc E s LB PC lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 E) fc None m (seg_rom rsegs)) mo).
Scheme kc__5 := Elimination for LinuxProcessSemantics.LinuxProcessSem.Run.config Sort Prop.

