  (* [comment removed for export] *)
  Definition msi_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (R q lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch [(lo, bv_unsigned sp); (q, q + 96); (R, R + 16)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' q (SpcHdrCells (mkSPC VP_SPCI_IMPL 1 1 1) j7)
      /\ rw_cells rsegs m' (q + 32) [CB 64 (zeros 64)]
      /\ rw_cells rsegs m' R [C8 (Z_to_bv 64 (q + 32)); C8 (Z_to_bv 64 q)].
Scheme kc__6 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

  Lemma msi_segB : forall sp gp tp t0 t1 t2 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (rax s1x s2x ra s0 : word) (F : bvmap 5 word) fc (m : mem) (R q lo : Z) (j7 junk jr : list byte),
    rw_cells rsegs m (bv_unsigned sp + -48) [C8 (Z_to_bv 64 0)] ->
    rw_cells rsegs m (bv_unsigned sp + -40) [C8 (Z_to_bv 64 q)] ->
    rw_cells rsegs m (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells rsegs m q (SpcHdrCells (mkSPC VP_SPCI_IMPL 1 1 0) j7) ->
    rw_cells rsegs m (q + 32) [CB 64 junk] ->
    rw_cells rsegs m R [CB 16 jr] ->
    XStatics m ->
    stk rsegs m lo (bv_unsigned sp + -48) -> lo + 48 <= bv_unsigned sp -> hceil <= lo ->
    0 < q -> q mod 16 = 0 -> q + 96 <= lo -> R + 16 <= lo -> (R + 16 <= q \/ q + 96 <= R) ->
    mem_inv rsegs m ->
    evt rsegs (msi_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R q lo j7 m)
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2
               (Z_to_bv 64 R) s1x (Z_to_bv 64 q) a1 a2 a3 a4 a5 a6 a7
               s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
