  (* [comment removed for export] *)
  Definition make_shared_impl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (R lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p : bptr) (q : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ rblock_range q SZ_SPCI_IMPL /\ hs_RHEAP H s' ((p, q, SZ_SPCI_IMPL) :: LB) m'
      /\ rw_cells rsegs m' R [C8 (wz (q + O_SPC_STORAGE)); C8 (wz q)]
      /\ ImplBlock ((p, q, SZ_SPCI_IMPL) :: LB) m' q (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 1) 0 0 [] 0)
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(R, R + 16)] m m'.

  Definition make_shared_impl_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (R lo B : Z) (errv : word) (jr : list byte),
      a0 = Z_to_bv 64 R ->
      rw_cells rsegs m R [CB 16 jr] -> (exists b, In b LB /\ blk_addr b <= R /\ R + 16 <= blk_addr b + blk_size b) ->
      XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + SZ_SPCI_IMPL <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - MAKE_SHARED_IMPL_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      hs_SR H (make_shared_impl_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB R lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_MAKE_SHARED_IMPL) fc None m (seg_rom rsegs)) mo).

  Lemma make_shared_impl_spec : make_shared_impl_stmt.
