Definition ANYEX_COPY_STACK : Z := 16.

Definition anyex_copy_post (ra sp gp tp s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (D S ioc lo : Z) (jd : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 a3 a4 m' jm,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz D) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (D, D + 48)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
