(* [comment removed for export] *)
Definition ANYEX_MOVE_STACK : Z := 16.

Definition anyex_move_post (ra sp gp tp s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (D S ioc lo : Z) (j16 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 m' jm,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz D) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (D, D + 48); (S, S + 48)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' D [C8 (wz ioc); CB 16 jm; C8 (wz T_ANYEX_OBJECT_FNS); C8 (wz D); C8 (wz T_ANYEX_TARGET_FNS)]
    /\ rw_cells rsegs m' S [C8 (wz ioc); CB 16 j16; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz T_ANYEX_PROP_FNS)].

Definition anyex_move_stmt : Prop :=
  forall (D S ioc lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (jd j16 : list byte),
  rw_cells rsegs m D [CB 48 jd] -> rw_cells rsegs m S (AnyExecCells S ioc j16) -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + ANYEX_MOVE_STACK <= bv_unsigned sp -> hceil <= lo ->
  (D + 48 <= lo \/ bv_unsigned sp <= D) -> (S + 56 <= lo \/ bv_unsigned sp <= S) -> (S + 56 <= D \/ D + 48 <= S) ->
  (D + 48 <= 0x10000 \/ 0xb4000 <= D) -> (S + 56 <= 0x10000 \/ 0xb4000 <= S) ->
  0 <= ioc < 2^64 -> 0 < S -> bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (anyex_move_post ra sp gp tp s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc D S ioc lo j16 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz D) (wz S) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_ANYEX_MOVE) fc None m (seg_rom rsegs)).

