(* [comment removed for export] *)
Definition ANYEX_QUERY_STACK : Z := 32.

Definition anyex_query_ctx_post (ra sp gp tp s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (ioc lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a1 a2 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz ioc) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp).

Definition anyex_query_ctx_stmt : Prop :=
  forall (E ioc lo : Z) ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (j16 : list byte),
  ro_cells rsegs m E (AnyExecCells E ioc j16) -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + ANYEX_QUERY_STACK <= bv_unsigned sp -> hceil <= lo ->
  (E + 56 <= lo \/ bv_unsigned sp <= E) ->
  0 <= ioc < 2^64 -> ioc mod 4 = 0 -> 0 < E -> bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (anyex_query_ctx_post ra sp gp tp s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc ioc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz E) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_ANYEX_QUERY_CONTEXT) fc None m (seg_rom rsegs)).

